package main

import "fmt"

func round(left, right, key byte) (byte, byte) {
	return right, left^(right+key)
}

func encrypt(left, right byte, keys []byte) (byte, byte) {
	for _, key := range keys {
		left, right = round(left, right, key)
	}
	return left, right
}

func decrypt(left, right byte, keys []byte) (byte, byte) {
	for i := len(keys) - 1; i >= 0; i-- {
		left, right = right^(left+keys[i]), left
	}
	return left, right
}

func main() {
	l, r := encrypt(0x12, 0x34, []byte{1})
	l, r = decrypt(l, r, []byte{1, 2})
	fmt.Println(l == 0x12 && r == 0x34)
}

